import sys

def merge_sorted_array_opt(nums1, m, nums2, n):
    temp = []
    i, j = 0, 0
    while i < m and j < n:
        if nums1[i] <= nums2[j]:
            temp.append(nums1[i])
            i += 1
        else:
            temp.append(nums2[j])
            j += 1
    while i < m:
        temp.append(nums1[i])
        i += 1
    while j < n:
        temp.append(nums2[j])
        j += 1
    for k in range(m + n):
        nums1[k] = temp[k]

if __name__ == '__main__':
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit(0)
    it = iter(data)
    m = int(next(it))
    n = int(next(it))
    nums1 = [0] * (m + n)
    for i in range(m):
        nums1[i] = int(next(it))
    nums2 = [int(next(it)) for _ in range(n)]
    merge_sorted_array_opt(nums1, m, nums2, n)
    print(' '.join(map(str, nums1)))
